package org.springframework.samples.petclinic.rest.function.owner;

import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.model.Owner;
import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
import org.springframework.samples.petclinic.repository.OwnerRepository;

/**
 * Flags a new owner as a possible (soft) duplicate. A hard duplicate — an equal
 * {@link OwnerIdentityKey} — is already rejected earlier by {@link CheckUniqueOwnerIdentity}; this
 * step runs after {@link BuildOwner} and before {@link SaveOwner}, so it compares against the owners
 * already stored, not the one being created. When an existing owner has a different identity key but
 * the same {@link OwnerSoundex} code for its last name and the same postcode, {@code possibleDuplicate}
 * is set true and {@code possibleDuplicateOf} to that owner's id; otherwise {@code possibleDuplicate}
 * is false and {@code possibleDuplicateOf} null. An owner that declared it shares a household
 * ({@code sharesHousehold} true) is never flagged — a declared household member is not a suspected
 * duplicate. Both values are persisted so they are returned unchanged on later reads of the owner.
 */
public class AssignOwnerPossibleDuplicate {

    public void service(@Val OwnerFieldsDto request, @Val Owner owner, OwnerRepository ownerRepository) {
        String postcode = owner.getPostcode();
        String soundex = OwnerSoundex.of(owner.getLastName());
        String identityKey = OwnerIdentityKey.of(owner);
        owner.setPossibleDuplicate(false);
        owner.setPossibleDuplicateOf(null);
        if (Boolean.TRUE.equals(request.getSharesHousehold())) {
            return; // a declared household member is not a suspected duplicate
        }
        if (postcode == null) {
            return; // no postcode to share, so never a soft-match
        }
        for (Owner existing : ownerRepository.findAll()) {
            if (Boolean.TRUE.equals(existing.getDeleted())) {
                continue; // a soft-deleted owner is not a duplicate match
            }
            if (!identityKey.equals(OwnerIdentityKey.of(existing))
                    && soundex.equals(OwnerSoundex.of(existing.getLastName()))
                    && postcode.equals(existing.getPostcode())) {
                owner.setPossibleDuplicate(true);
                owner.setPossibleDuplicateOf(existing.getId());
                return;
            }
        }
    }
}
package org.springframework.samples.petclinic.rest.function.owner;

import java.util.Locale;
import java.util.Set;

import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
import org.springframework.samples.petclinic.rest.escalation.DisposableEmailDomainException;

/**
 * Rejects an email whose domain is on the disposable-domain blocklist. Email is optional, so an
 * absent or blank email is accepted. Runs after {@link NormalizeOwnerEmail}, which has already
 * lower-cased and syntactically validated the address, so the domain is the substring after the
 * final {@code @}. A blocklisted domain is rejected with 400 via
 * {@link DisposableEmailDomainException}.
 */
public class RejectDisposableEmailDomain {

    private static final Set<String> BLOCKED_DOMAINS = Set.of(
            "mailinator.com",
            "tempmail.com",
            "guerrillamail.com");

    public void service(@Val OwnerFieldsDto request) throws DisposableEmailDomainException {
        String email = request.getEmail();
        if (email == null || email.isBlank()) {
            return; // optional when absent
        }
        int at = email.lastIndexOf('@');
        if (at < 0) {
            return; // not a syntactically valid address; NormalizeOwnerEmail already guards this
        }
        String domain = email.substring(at + 1).toLowerCase(Locale.ROOT);
        if (BLOCKED_DOMAINS.contains(domain)) {
            throw new DisposableEmailDomainException(email);
        }
    }
}
package org.springframework.samples.petclinic.rest.function.owner;

import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
import org.springframework.samples.petclinic.rest.escalation.CityAtCapacityException;
import org.springframework.samples.petclinic.repository.OwnerRepository;

/**
 * Runs on {@code POST /api/owners} before {@link BuildOwner} (so no owner is created on conflict):
 * rejects the request with 409 via {@link CityAtCapacityException} when the request's city already
 * contains {@link OwnerCityCounts#MAX_OWNERS_PER_CITY} or more owners, compared case-insensitively
 * with collapsed whitespace.
 */
public class CheckOwnerCityCapacity {

    public void service(@Val OwnerFieldsDto request, OwnerRepository ownerRepository)
            throws CityAtCapacityException {
        if (OwnerCityCounts.countInCity(ownerRepository, request.getCity())
                >= OwnerCityCounts.MAX_OWNERS_PER_CITY) {
            throw new CityAtCapacityException(request.getCity());
        }
    }
}

